//! Toolchain catalogue: where to download and how to verify (ARCHITECTURE §6.3, ADR-034, ADR-077).
//!
//! | Tool | Source | Verification |
//! |---|---|---|
//! | uv | GitHub releases, [`UV_PINNED`] | sha256 embedded per target (generated by `cargo xtask tool-checksums`) |
//! | node | `nodejs.org/dist` (official), `unofficial-builds.nodejs.org` (musl, riscv64, …) | `SHASUMS256.txt` over TLS |
//! | go | `dl.google.com/go` (pre-commit's `golang.py` URL) | sha256 of the go.dev JSON (`include=all`) over TLS |
//! | rustup-init | `static.rust-lang.org/rustup` | `.sha256` sidecar over TLS |
//! | rbenv, ruby-build, ruby-download | embedded: pre-commit 4.7.0's `resources/*.tar.gz` | sha256 embedded |
//!
//! Every URL returned here is the canonical one; [`crate::HttpFetch`] applies the mirror overrides (`SNP_NODE_MIRROR`
//! for archives; `SNP_NODE_SHASUMS_URL`/`SNP_GO_JSON_URL`, which must be https, for manifests), so an `http://` mirror
//! allowed by `SNP_ALLOW_INSECURE_MIRROR` only ever serves bytes that a TLS manifest or an embedded digest verifies.
//!
//! Owner: WP-16.

use std::io;

use serde_json::Value;

use crate::generated::uv_checksums;
use crate::policy::{GO_JSON_ALL, GO_JSON_LATEST, NODE_DIST, NODE_UNOFFICIAL};
use crate::{Checksum, Fetch, NetError};

/// A downloadable toolchain.
#[derive(Copy, Clone, Debug, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum Tool {
    /// uv (Python environments).
    Uv,
    /// Node.js.
    Node,
    /// Go.
    Go,
    /// rustup-init.
    Rustup,
    /// ruby-build.
    RubyBuild,
    /// rbenv.
    Rbenv,
    /// pre-commit's `ruby-download` rbenv plugin (`rbenv download`, `ruby.py:96-103`), embedded like rbenv and
    /// ruby-build (additive to ARCHITECTURE §1.4.9: pre-commit 4.7.0 vendors three ruby archives).
    RubyDownload,
}

/// What to download and how to verify it.
#[derive(Clone, Debug)]
pub struct Artifact {
    /// Download URL.
    pub url: String,
    /// Expected digest.
    pub checksum: Checksum,
    /// How to unpack it.
    pub layout: Layout,
}

/// Archive layout of an [`Artifact`].
#[derive(Clone, Debug)]
#[non_exhaustive]
pub enum Layout {
    /// `.tar.gz` with leading components stripped.
    TarGz {
        /// Components to strip.
        strip: u8,
    },
    /// `.tar.xz` with leading components stripped.
    TarXz {
        /// Components to strip.
        strip: u8,
    },
    /// `.zip` with leading components stripped.
    Zip {
        /// Components to strip.
        strip: u8,
    },
    /// A single executable.
    Executable,
}

/// The pinned uv version (+ embedded sha256 per target triple, generated table).
pub const UV_PINNED: &str = uv_checksums::UV_VERSION;

/// The release the ruby helpers come from (pre-commit 4.7.0 vendors rbenv 1.3.2 and ruby-build 20251023).
const RBENV_VERSION: &str = "1.3.2";
/// See [`RBENV_VERSION`].
const RUBY_BUILD_VERSION: &str = "20251023";
/// `ruby-download` carries no version of its own: it is the copy vendored by pre-commit 4.6.2, byte-identical in
/// 4.7.0 (the name is kept so existing tool caches stay valid, ADR-089).
const RUBY_DOWNLOAD_VERSION: &str = "pre-commit-4.6.2";

/// URL scheme of the embedded archives (served from the binary by [`crate::HttpFetch::get_verified`]).
const EMBEDDED_SCHEME: &str = "snp-embedded:";

/// The embedded archives: (URL, bytes, sha256 hex). The digests are re-checked by a unit test.
const EMBEDDED: [(&str, &[u8], &str); 3] = [
    (
        "snp-embedded:rbenv-1.3.2.tar.gz",
        include_bytes!("embedded/rbenv.tar.gz"),
        "e3a75912308ad22bfaf6a9907ef7070dd347c47f525b9d52ae25897d4bd15356",
    ),
    (
        "snp-embedded:ruby-build-20251023.tar.gz",
        include_bytes!("embedded/ruby-build.tar.gz"),
        "36322fac5ddc177c510c3ae0b79cae22005f85c4fd4cf9f7a8d403b835d04839",
    ),
    (
        "snp-embedded:ruby-download-pre-commit-4.6.2.tar.gz",
        include_bytes!("embedded/ruby-download.tar.gz"),
        "994ffb9cb15cfbb1446dff4e08d56d1c694a18d85eeae19968b34a795e2a9c27",
    ),
];

/// The bytes of an embedded archive URL (`snp-embedded:…`, as returned by [`resolve`] for the ruby helpers), so that
/// any [`Fetch`] implementation can serve them; `None` for every other URL.
pub fn embedded(url: &str) -> Option<&'static [u8]> {
    if !url.starts_with(EMBEDDED_SCHEME) {
        return None;
    }
    EMBEDDED
        .iter()
        .find(|(u, _, _)| *u == url)
        .map(|(_, bytes, _)| *bytes)
}

/// Crate-internal alias used by the fetcher.
pub(crate) fn embedded_bytes(url: &str) -> Option<&'static [u8]> {
    embedded(url)
}

/// Caps of the manifests fetched here.
const MAX_SHASUMS: u64 = 1 << 20;
/// The go.dev JSON with every release is ~2.2 MB (2026).
const MAX_GO_JSON: u64 = 16 << 20;
/// node's `index.json`.
const MAX_NODE_INDEX: u64 = 16 << 20;
/// A `.sha256` sidecar or `release-stable.toml`.
const MAX_SMALL: u64 = 64 << 10;

/// Checksum manifests (`SHASUMS256.txt`, go.dev JSON, `.sha256`) are always fetched over https from the canonical
/// origin (or an explicit https `SNP_NODE_SHASUMS_URL`/`SNP_GO_JSON_URL`), never from an `http://` mirror allowed by
/// `SNP_ALLOW_INSECURE_MIRROR` — a non-TLS mirror then only serves bytes that the TLS manifest verifies.
///
/// `version` is a concrete version (`22.11.0`/`v22.11.0`, `1.23.2`/`go1.23.2`, a rustup version) or an alias that
/// [`resolve_version`] understands (`default`, `latest`; node `lts`). A version or file the origin does not list is
/// `NetError::Http { status: 404 }` for the archive URL (backends map it to pre-commit's texts, e.g. golang's
/// `ValueError`); a target without a build is an `Unsupported` I/O error.
pub fn resolve(
    tool: Tool,
    version: &str,
    target: &str,
    f: &dyn Fetch,
) -> Result<Artifact, NetError> {
    let version = resolve_version(tool, version, target, f)?;
    match tool {
        Tool::Uv => uv(&version, target),
        Tool::Node => node(&version, target, f),
        Tool::Go => go(&version, target, f),
        Tool::Rustup => rustup(&version, target, f),
        Tool::Rbenv | Tool::RubyBuild | Tool::RubyDownload => ruby_helper(tool, &version),
    }
}

/// The concrete version an alias stands for on `target`: `default`/`latest`/`""` (every tool), node `lts`; `v`/`go`
/// prefixes are dropped. uv's default is [`UV_PINNED`]; node's is the newest release of `index.json` that is not a
/// pre-release (no `-` in the version) and lists a build for `target` (nodeenv 1.12.0 `_get_last_node_version`:
/// `_is_prerelease`, `_has_platform_build`), `lts` the newest such LTS; musl and the unofficial-only architectures
/// read the unofficial builds' `index.json` (arm64-musl exists only there). go's is the first stable release of the
/// go.dev list (`golang.py` `_infer_go_version`); rustup's is the current `release-stable.toml` version; the ruby
/// helpers have exactly one (embedded) version each. Only node's aliases depend on `target`.
pub fn resolve_version(
    tool: Tool,
    requested: &str,
    target: &str,
    f: &dyn Fetch,
) -> Result<String, NetError> {
    let alias = matches!(requested, "" | "default" | "latest");
    let v = match tool {
        Tool::Uv if alias => UV_PINNED.to_owned(),
        Tool::Node if alias || requested == "lts" => node_alias(requested == "lts", target, f)?,
        Tool::Node => requested.strip_prefix('v').unwrap_or(requested).to_owned(),
        Tool::Go if alias => go_latest(f)?,
        Tool::Go => requested.strip_prefix("go").unwrap_or(requested).to_owned(),
        Tool::Rustup if alias => rustup_latest(f)?,
        Tool::Rbenv if alias => RBENV_VERSION.to_owned(),
        Tool::RubyBuild if alias => RUBY_BUILD_VERSION.to_owned(),
        Tool::RubyDownload if alias => RUBY_DOWNLOAD_VERSION.to_owned(),
        _ => requested.to_owned(),
    };
    check_version(tool, &v)?;
    Ok(v)
}

/// Versions are interpolated into URLs and directory names: `[0-9A-Za-z._+-]{1,64}` only.
fn check_version(tool: Tool, v: &str) -> Result<(), NetError> {
    let ok = !v.is_empty()
        && v.len() <= 64
        && v.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b".-_+".contains(&b));
    if ok {
        Ok(())
    } else {
        Err(NetError::Io(io::Error::new(
            io::ErrorKind::InvalidInput,
            format!("invalid {tool:?} version {v:?}"),
        )))
    }
}

/// No build of `tool` exists for `target`.
fn unsupported(tool: Tool, target: &str) -> NetError {
    NetError::Io(io::Error::new(
        io::ErrorKind::Unsupported,
        format!("no {tool:?} build for target {target:?}"),
    ))
}

/// The origin does not list the file.
fn not_found(url: &str) -> NetError {
    NetError::Http {
        url: url.to_owned(),
        status: 404,
    }
}

/// A manifest that cannot be understood.
fn malformed(url: &str, what: &str) -> NetError {
    NetError::Transport {
        url: url.to_owned(),
        msg: format!("malformed {what}"),
    }
}

/// The parts of a target triple the catalogue needs.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct Platform {
    /// Architecture as the triple spells it (`x86_64`, `aarch64`, `riscv64gc`, …).
    arch: &'static str,
    /// Operating system.
    os: Os,
    /// musl libc (`*-linux-musl*`).
    musl: bool,
}

/// The operating systems with toolchain builds.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Os {
    /// Linux.
    Linux,
    /// macOS.
    Darwin,
    /// Windows.
    Windows,
    /// FreeBSD (go only).
    FreeBsd,
}

/// Parses `target` (`x86_64-unknown-linux-gnu`, `aarch64-apple-darwin`, `x86_64-pc-windows-msvc`, …).
fn platform(target: &str) -> Option<Platform> {
    let (arch, rest) = target.split_once('-')?;
    let arch = match arch {
        "x86_64" => "x86_64",
        "aarch64" => "aarch64",
        "i686" | "i586" => "i686",
        "armv7" => "armv7",
        "arm" => "arm",
        "riscv64gc" | "riscv64" => "riscv64gc",
        "powerpc64le" => "powerpc64le",
        "s390x" => "s390x",
        "loongarch64" => "loongarch64",
        _ => return None,
    };
    let os = if rest.contains("linux") {
        Os::Linux
    } else if rest.contains("apple-darwin") {
        Os::Darwin
    } else if rest.contains("windows") {
        Os::Windows
    } else if rest.contains("freebsd") {
        Os::FreeBsd
    } else {
        return None;
    };
    Some(Platform {
        arch,
        os,
        musl: rest.contains("musl"),
    })
}

/// The pinned uv archive for `target` (embedded checksum; no network).
fn uv(version: &str, target: &str) -> Result<Artifact, NetError> {
    if version != UV_PINNED {
        return Err(NetError::Io(io::Error::new(
            io::ErrorKind::NotFound,
            format!("no embedded checksum for uv {version} (snp pins uv {UV_PINNED})"),
        )));
    }
    let (_, ext, hex) = uv_checksums::UV_ARCHIVES
        .iter()
        .find(|(t, _, _)| *t == target)
        .ok_or_else(|| unsupported(Tool::Uv, target))?;
    let checksum = Checksum::sha256_hex(hex).ok_or_else(|| unsupported(Tool::Uv, target))?;
    let layout = if *ext == "zip" {
        // The Windows zips hold `uv.exe`, `uvx.exe`, `uvw.exe` at the top level.
        Layout::Zip { strip: 0 }
    } else {
        // The tarballs hold `uv-<target>/uv` and `uv-<target>/uvx`.
        Layout::TarGz { strip: 1 }
    };
    Ok(Artifact {
        url: format!(
            "https://github.com/astral-sh/uv/releases/download/{version}/uv-{target}.{ext}"
        ),
        checksum,
        layout,
    })
}

/// node's file-name platform (`linux-x64`, `darwin-arm64`, `win-x64`, `linux-x64-musl`, …) and whether only the
/// unofficial builds can have it.
fn node_platform(p: Platform) -> Option<(String, bool)> {
    let arch = match (p.arch, p.os) {
        ("x86_64", _) => "x64",
        ("aarch64", _) => "arm64",
        ("i686", Os::Windows) => "x86",
        ("armv7", Os::Linux) => "armv7l",
        ("arm", Os::Linux) => "armv6l",
        ("riscv64gc", Os::Linux) => "riscv64",
        ("powerpc64le", Os::Linux) => "ppc64le",
        ("s390x", Os::Linux) => "s390x",
        ("loongarch64", Os::Linux) => "loong64",
        _ => return None,
    };
    let os = match p.os {
        Os::Linux => "linux",
        Os::Darwin => "darwin",
        Os::Windows => "win",
        Os::FreeBsd => return None,
    };
    let musl = if p.musl { "-musl" } else { "" };
    let unofficial_only = matches!(arch, "riscv64" | "loong64" | "armv6l");
    Some((format!("{os}-{arch}{musl}"), p.musl || unofficial_only))
}

/// A node archive verified by the `SHASUMS256.txt` of the official builds, falling back to the unofficial builds for
/// musl and the architectures only they cover.
fn node(version: &str, target: &str, f: &dyn Fetch) -> Result<Artifact, NetError> {
    let p = platform(target).ok_or_else(|| unsupported(Tool::Node, target))?;
    let (plat, try_unofficial) = node_platform(p).ok_or_else(|| unsupported(Tool::Node, target))?;
    let (ext, layout) = if p.os == Os::Windows {
        ("zip", Layout::Zip { strip: 1 })
    } else if cfg!(feature = "xz") {
        ("tar.xz", Layout::TarXz { strip: 1 })
    } else {
        ("tar.gz", Layout::TarGz { strip: 1 })
    };
    let file = format!("node-v{version}-{plat}.{ext}");
    let bases: &[&str] = if try_unofficial {
        &[NODE_DIST, NODE_UNOFFICIAL]
    } else {
        &[NODE_DIST]
    };
    let mut last_url = String::new();
    for base in bases {
        let url = format!("{base}/v{version}/{file}");
        let sums_url = format!("{base}/v{version}/SHASUMS256.txt");
        let sums = match f.get_text(&sums_url, MAX_SHASUMS) {
            Ok(s) => s,
            Err(NetError::Http { status: 404, .. }) => {
                last_url = url;
                continue;
            }
            Err(e) => return Err(e),
        };
        if let Some(checksum) = shasums_lookup(&sums, &file) {
            return Ok(Artifact {
                url,
                checksum,
                layout,
            });
        }
        last_url = url;
    }
    Err(not_found(&last_url))
}

/// The digest of `file` in a `SHASUMS256.txt` (`<hex>  <name>` or `<hex> *<name>` lines).
fn shasums_lookup(sums: &str, file: &str) -> Option<Checksum> {
    sums.lines().find_map(|line| {
        let mut it = line.split_whitespace();
        let hex = it.next()?;
        let name = it.next()?;
        let name = name.strip_prefix('*').unwrap_or(name);
        (name == file && it.next().is_none())
            .then(|| Checksum::sha256_hex(hex))
            .flatten()
    })
}

/// The key of `index.json`'s `files` for node's file-name platform `plat` (`linux-x64`, `osx-arm64-tar`,
/// `win-x64-zip`, `linux-arm64-musl`, …).
fn node_index_key(plat: &str) -> String {
    if let Some(rest) = plat.strip_prefix("darwin-") {
        format!("osx-{rest}-tar")
    } else if plat.starts_with("win-") {
        format!("{plat}-zip")
    } else {
        plat.to_owned()
    }
}

/// The newest non-pre-release (or LTS) node with a build for `target`, without the `v`; `Unsupported` when none.
fn node_alias(lts: bool, target: &str, f: &dyn Fetch) -> Result<String, NetError> {
    let p = platform(target).ok_or_else(|| unsupported(Tool::Node, target))?;
    let (plat, unofficial) = node_platform(p).ok_or_else(|| unsupported(Tool::Node, target))?;
    let key = node_index_key(&plat);
    let base = if unofficial {
        NODE_UNOFFICIAL
    } else {
        NODE_DIST
    };
    let url = format!("{base}/index.json");
    let text = f.get_text(&url, MAX_NODE_INDEX)?;
    let index: Value =
        serde_json::from_str(&text).map_err(|_| malformed(&url, "node index.json"))?;
    let releases = index
        .as_array()
        .ok_or_else(|| malformed(&url, "node index.json"))?;
    let pick = releases.iter().find_map(|r| {
        let v = r.get("version")?.as_str()?;
        let is_lts = r
            .get("lts")
            .is_some_and(|l| !matches!(l, Value::Bool(false) | Value::Null));
        let has_build = r
            .get("files")?
            .as_array()?
            .iter()
            .any(|f| f.as_str() == Some(key.as_str()));
        (!v.contains('-') && (!lts || is_lts) && has_build).then_some(v)
    });
    let v = pick.ok_or_else(|| unsupported(Tool::Node, target))?;
    Ok(v.strip_prefix('v').unwrap_or(v).to_owned())
}

/// go's `os-arch` of the archive file name.
fn go_platform(p: Platform) -> Option<(&'static str, &'static str)> {
    let arch = match p.arch {
        "x86_64" => "amd64",
        "aarch64" => "arm64",
        "i686" => "386",
        "armv7" | "arm" => "armv6l",
        "riscv64gc" => "riscv64",
        "powerpc64le" => "ppc64le",
        "s390x" => "s390x",
        "loongarch64" => "loong64",
        _ => return None,
    };
    let os = match p.os {
        Os::Linux => "linux",
        Os::Darwin => "darwin",
        Os::Windows => "windows",
        Os::FreeBsd => "freebsd",
    };
    Some((os, arch))
}

/// pre-commit's go archive URL (`golang.py` `_get_url`), verified by the go.dev JSON.
fn go(version: &str, target: &str, f: &dyn Fetch) -> Result<Artifact, NetError> {
    let p = platform(target).ok_or_else(|| unsupported(Tool::Go, target))?;
    let (os, arch) = go_platform(p).ok_or_else(|| unsupported(Tool::Go, target))?;
    let (ext, layout) = if p.os == Os::Windows {
        ("zip", Layout::Zip { strip: 1 })
    } else {
        ("tar.gz", Layout::TarGz { strip: 1 })
    };
    let file = format!("go{version}.{os}-{arch}.{ext}");
    let url = format!("https://dl.google.com/go/{file}");
    let text = f.get_text(GO_JSON_ALL, MAX_GO_JSON)?;
    let releases: Value =
        serde_json::from_str(&text).map_err(|_| malformed(GO_JSON_ALL, "go.dev JSON"))?;
    let releases = releases
        .as_array()
        .ok_or_else(|| malformed(GO_JSON_ALL, "go.dev JSON"))?;
    let want = format!("go{version}");
    let checksum = releases
        .iter()
        .filter(|r| r.get("version").and_then(Value::as_str) == Some(want.as_str()))
        .filter_map(|r| r.get("files").and_then(Value::as_array))
        .flatten()
        .find(|file_entry| {
            file_entry.get("filename").and_then(Value::as_str) == Some(file.as_str())
                && file_entry.get("kind").and_then(Value::as_str) == Some("archive")
        })
        .and_then(|file_entry| file_entry.get("sha256").and_then(Value::as_str))
        .and_then(Checksum::sha256_hex)
        .ok_or_else(|| not_found(&url))?;
    Ok(Artifact {
        url,
        checksum,
        layout,
    })
}

/// The first stable release of the go.dev list, without `go`.
fn go_latest(f: &dyn Fetch) -> Result<String, NetError> {
    let text = f.get_text(GO_JSON_LATEST, MAX_GO_JSON)?;
    let releases: Value =
        serde_json::from_str(&text).map_err(|_| malformed(GO_JSON_LATEST, "go.dev JSON"))?;
    let v = releases
        .as_array()
        .and_then(|rs| {
            rs.iter()
                .find(|r| r.get("stable").and_then(Value::as_bool) != Some(false))
        })
        .and_then(|r| r.get("version"))
        .and_then(Value::as_str)
        .ok_or_else(|| malformed(GO_JSON_LATEST, "go.dev JSON"))?;
    Ok(v.strip_prefix("go").unwrap_or(v).to_owned())
}

/// The rustup origin.
const RUSTUP_ROOT: &str = "https://static.rust-lang.org/rustup";

/// rustup-init for `target`, verified by its `.sha256` sidecar.
fn rustup(version: &str, target: &str, f: &dyn Fetch) -> Result<Artifact, NetError> {
    let p = platform(target).ok_or_else(|| unsupported(Tool::Rustup, target))?;
    let exe = if p.os == Os::Windows {
        "rustup-init.exe"
    } else {
        "rustup-init"
    };
    let url = format!("{RUSTUP_ROOT}/archive/{version}/{target}/{exe}");
    let sidecar = format!("{url}.sha256");
    let text = match f.get_text(&sidecar, MAX_SMALL) {
        Ok(t) => t,
        Err(NetError::Http { status: 404, .. }) => return Err(not_found(&url)),
        Err(e) => return Err(e),
    };
    let checksum = text
        .split_whitespace()
        .next()
        .and_then(Checksum::sha256_hex)
        .ok_or_else(|| malformed(&sidecar, "checksum file"))?;
    Ok(Artifact {
        url,
        checksum,
        layout: Layout::Executable,
    })
}

/// The current rustup version (`release-stable.toml`: `version = '1.29.1'`).
fn rustup_latest(f: &dyn Fetch) -> Result<String, NetError> {
    let url = format!("{RUSTUP_ROOT}/release-stable.toml");
    let text = f.get_text(&url, MAX_SMALL)?;
    text.lines()
        .find_map(|l| {
            let (k, v) = l.split_once('=')?;
            (k.trim() == "version").then(|| v.trim().trim_matches(['\'', '"']).to_owned())
        })
        .filter(|v| !v.is_empty())
        .ok_or_else(|| malformed(&url, "release-stable.toml"))
}

/// The embedded ruby helper archive of `tool` (each archive holds one top-level directory named after the tool,
/// exactly as pre-commit 4.7.0 vendors it).
fn ruby_helper(tool: Tool, version: &str) -> Result<Artifact, NetError> {
    let (url, want) = match tool {
        Tool::Rbenv => ("snp-embedded:rbenv-1.3.2.tar.gz", RBENV_VERSION),
        Tool::RubyBuild => (
            "snp-embedded:ruby-build-20251023.tar.gz",
            RUBY_BUILD_VERSION,
        ),
        _ => (
            "snp-embedded:ruby-download-pre-commit-4.6.2.tar.gz",
            RUBY_DOWNLOAD_VERSION,
        ),
    };
    if version != want {
        return Err(NetError::Io(io::Error::new(
            io::ErrorKind::NotFound,
            format!("snp embeds {tool:?} {want} only, not {version}"),
        )));
    }
    let hex = EMBEDDED
        .iter()
        .find(|(u, _, _)| *u == url)
        .map_or("", |(_, _, h)| *h);
    let checksum = Checksum::sha256_hex(hex).ok_or_else(|| malformed(url, "embedded digest"))?;
    Ok(Artifact {
        url: url.to_owned(),
        checksum,
        layout: Layout::TarGz { strip: 0 },
    })
}

/// e.g. "x86_64-unknown-linux-gnu" (musl/riscv64 aware).
///
/// The triple snp itself was built for, which is the platform whose toolchain builds it downloads (an `x86_64` snp
/// under Rosetta or `WoW64` downloads `x86_64` toolchains, like an `x86_64` Python running pre-commit).
pub fn host_target() -> &'static str {
    HOST_TARGET
}

