#[cfg(test)]
mod tests {
    use sha2::{Digest, Sha256};

    use super::*;

    #[test]
    fn embedded_digests_match_their_bytes() {
        for (url, bytes, hex) in EMBEDDED {
            let actual = crate::error::to_hex(&Sha256::digest(bytes));
            assert_eq!(actual, hex, "{url}");
            assert_eq!(embedded(url), Some(bytes));
        }
        assert_eq!(embedded("https://example.com/x"), None);
        assert_eq!(embedded("snp-embedded:nope"), None);
    }

    #[test]
    fn platforms() {
        assert_eq!(
            platform("x86_64-unknown-linux-musl"),
            Some(Platform {
                arch: "x86_64",
                os: Os::Linux,
                musl: true
            })
        );
        assert_eq!(
            platform("aarch64-apple-darwin").map(|p| p.os),
            Some(Os::Darwin)
        );
        assert_eq!(platform("wasm32-unknown-unknown"), None);
        assert_eq!(
            node_platform(platform("riscv64gc-unknown-linux-gnu").unwrap()),
            Some(("linux-riscv64".to_owned(), true))
        );
        assert_eq!(
            node_platform(platform("aarch64-pc-windows-msvc").unwrap()),
            Some(("win-arm64".to_owned(), false))
        );
        // The `files` keys of node's `index.json` (official and unofficial builds, 2026).
        for (plat, key) in [
            ("linux-x64", "linux-x64"),
            ("linux-arm64-musl", "linux-arm64-musl"),
            ("darwin-x64", "osx-x64-tar"),
            ("darwin-arm64", "osx-arm64-tar"),
            ("win-x64", "win-x64-zip"),
            ("win-arm64", "win-arm64-zip"),
        ] {
            assert_eq!(node_index_key(plat), key);
        }
        assert_eq!(
            go_platform(platform("x86_64-pc-windows-msvc").unwrap()),
            Some(("windows", "amd64"))
        );
    }

    #[test]
    fn host_target_is_known() {
        assert_ne!(host_target(), "unknown");
        assert!(platform(host_target()).is_some());
    }

    #[test]
    fn shasums_parsing() {
        let sums = "aa  other\n\
                    4f862bab52039835efbe613b532238b6e4dde98d139a34e6923193e073438b13  node-v22.11.0-linux-x64.tar.gz\n\
                    83bf07dd343002a26211cf1fcd46a9d9534219aad42ee02847816940bf610a72 *node-v22.11.0-linux-x64.tar.xz\n";
        assert_eq!(
            shasums_lookup(sums, "node-v22.11.0-linux-x64.tar.gz").map(|c| c.hex()),
            Some("4f862bab52039835efbe613b532238b6e4dde98d139a34e6923193e073438b13".to_owned())
        );
        assert!(shasums_lookup(sums, "node-v22.11.0-linux-x64.tar.xz").is_some());
        assert!(shasums_lookup(sums, "node-v22.11.0-linux").is_none());
        assert!(shasums_lookup(sums, "other").is_none());
    }

    #[test]
    fn versions_are_url_safe() {
        assert!(check_version(Tool::Go, "1.22.1").is_ok());
        assert!(check_version(Tool::Node, "22.11.0").is_ok());
        let long: String = std::iter::repeat_n('9', 65).collect();
        for bad in ["", "1.2/../../x", "1 2", "a?b", &long] {
            assert!(check_version(Tool::Go, bad).is_err(), "{bad:?}");
        }
    }
}
